use vstd::prelude::*;
use vstd::vec::Vec;

// Pure spec‐level helper to decide if a lowercase letter is a vowel.
#[verifier(publish)]
#[pure]
fn is_vowel(c: char) -> bool {
    // We only ever call is_vowel on 'a'..='z', so no extra guards needed here.
    c == 'a'
     || c == 'e'
     || c == 'i'
     || c == 'o'
     || c == 'u'
}

// Main solver.
//   - requires: input has exactly one character, in 'a'..='z'.
//   - ensures: if that character is a vowel, returns ['v','o','w','e','l'];
//              otherwise returns ['c','o','n','s','o','n','a','n','t'].
#[verifier(publish)]
#[requires(input.len() == 1)]
#[requires('a' <= input[0] && input[0] <= 'z')]
#[ensures(
    if is_vowel(input[0]) {
        result == Vec::from_slice(&['v','o','w','e','l'])
    } else {
        result == Vec::from_slice(&['c','o','n','s','o','n','a','n','t'])
    }
)]
pub fn solve(input: Vec<char>) -> Vec<char> {
    let c = input[0];
    if is_vowel(c) {
        Vec::from_slice(&['v','o','w','e','l'])
    } else {
        Vec::from_slice(&['c','o','n','s','o','n','a','n','t'])
    }
}

// Optional: a trivial main illustrating usage.
fn main() {
    let v = solve(Vec::from_slice(&['a'])); // should be "vowel"
    let c = solve(Vec::from_slice(&['z'])); // should be "consonant"
    // (In a real Verus-verified binary, you wouldn't print—
    //  this is just to show the code compiles as Rust.)
    std::println!("{:?} {:?}", v, c);
}